begin;
create extension if not exists pgcrypto;
create table if not exists public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'user' check (role in ('user','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.subjects (id uuid primary key default gen_random_uuid(), slug text not null unique, code text not null, name text not null, description text not null default '', language text not null, is_published boolean not null default false, created_by uuid references public.profiles(user_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.question_sets (id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete cascade, schema_version integer not null check (schema_version > 0), source_file text not null, question_count integer not null check (question_count >= 0), version integer not null check (version > 0), content_hash text not null, is_published boolean not null default false, created_by uuid references public.profiles(user_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(subject_id, version), unique(subject_id, content_hash));
create table if not exists public.questions (id uuid primary key default gen_random_uuid(), question_set_id uuid not null references public.question_sets(id) on delete cascade, external_id text not null, number integer not null check (number > 0), type text not null check (type in ('single-choice','multiple-choice','true-false')), question text not null, options jsonb not null check (jsonb_typeof(options)='array'), correct_answer jsonb not null check (jsonb_typeof(correct_answer) in ('array','string')), explanation text, source jsonb not null default '{}'::jsonb check (jsonb_typeof(source)='object'), needs_review boolean not null default false, review_notes jsonb not null default '[]'::jsonb check (jsonb_typeof(review_notes)='array'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(question_set_id, external_id), unique(question_set_id, number));
create table if not exists public.user_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(user_id) on delete cascade, question_set_id uuid not null references public.question_sets(id) on delete cascade, mode text not null check (mode in ('learn','test')), current_question_id uuid references public.questions(id) on delete set null, current_question_index integer not null default 0 check (current_question_index >= 0), answered_question_ids jsonb not null default '[]'::jsonb check (jsonb_typeof(answered_question_ids)='array'), correct_question_ids jsonb not null default '[]'::jsonb check (jsonb_typeof(correct_question_ids)='array'), incorrect_question_ids jsonb not null default '[]'::jsonb check (jsonb_typeof(incorrect_question_ids)='array'), progress_payload jsonb not null default '{}'::jsonb check (jsonb_typeof(progress_payload)='object'), question_set_version integer not null check (question_set_version > 0), revision bigint not null default 0 check (revision >= 0), client_updated_at timestamptz not null, server_updated_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(user_id, question_set_id, mode));
create table if not exists public.question_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(user_id) on delete cascade, question_set_id uuid not null references public.question_sets(id) on delete cascade, question_id uuid not null references public.questions(id) on delete cascade, mode text not null check (mode in ('learn','test')), queue_instance_id text, selected_option_ids jsonb check (selected_option_ids is null or jsonb_typeof(selected_option_ids)='array'), result text not null check (result in ('correct','incorrect','dont-know')), answered_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists public.import_jobs (id uuid primary key default gen_random_uuid(), uploaded_by uuid not null references public.profiles(user_id) on delete cascade, original_filename text not null, content_hash text not null, status text not null check (status in ('pending','validating','completed','failed')), dry_run boolean not null default true, total_questions integer not null default 0 check (total_questions >= 0), inserted_count integer not null default 0 check (inserted_count >= 0), updated_count integer not null default 0 check (updated_count >= 0), skipped_count integer not null default 0 check (skipped_count >= 0), error_count integer not null default 0 check (error_count >= 0), report jsonb not null default '{}'::jsonb check (jsonb_typeof(report)='object'), completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(uploaded_by, content_hash, dry_run));
create table if not exists public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(user_id) on delete set null, action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata)='object'), created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where user_id=auth.uid() and role='admin') $$;
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(user_id,display_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''),'user') on conflict(user_id) do nothing; return new; end $$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create or replace function public.set_server_updated_at() returns trigger language plpgsql as $$ begin new.server_updated_at=now(); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
do $$ declare t text; begin foreach t in array array['profiles','subjects','question_sets','questions','import_jobs'] loop execute format('drop trigger if exists set_updated_at on public.%I',t); execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
drop trigger if exists set_server_updated_at on public.user_progress; create trigger set_server_updated_at before update on public.user_progress for each row execute function public.set_server_updated_at();
alter table public.profiles enable row level security; alter table public.subjects enable row level security; alter table public.question_sets enable row level security; alter table public.questions enable row level security; alter table public.user_progress enable row level security; alter table public.question_attempts enable row level security; alter table public.import_jobs enable row level security; alter table public.audit_logs enable row level security;
drop policy if exists profiles_select on public.profiles; create policy profiles_select on public.profiles for select using(user_id=auth.uid() or public.is_admin());
drop policy if exists profiles_update on public.profiles; create policy profiles_update on public.profiles for update using(user_id=auth.uid()) with check(user_id=auth.uid() and role=(select role from public.profiles where user_id=auth.uid()));
drop policy if exists subjects_read on public.subjects; create policy subjects_read on public.subjects for select using(is_published or public.is_admin());
drop policy if exists subjects_admin on public.subjects; create policy subjects_admin on public.subjects for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists question_sets_read on public.question_sets; create policy question_sets_read on public.question_sets for select using(is_published and exists(select 1 from public.subjects s where s.id=subject_id and s.is_published) or public.is_admin());
drop policy if exists question_sets_admin on public.question_sets; create policy question_sets_admin on public.question_sets for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists questions_read on public.questions; create policy questions_read on public.questions for select using(exists(select 1 from public.question_sets qs join public.subjects s on s.id=qs.subject_id where qs.id=question_set_id and qs.is_published and s.is_published) or public.is_admin());
drop policy if exists questions_admin on public.questions; create policy questions_admin on public.questions for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists progress_own on public.user_progress; create policy progress_own on public.user_progress for all using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists attempts_own on public.question_attempts; create policy attempts_own on public.question_attempts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists imports_admin on public.import_jobs; create policy imports_admin on public.import_jobs for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists audit_read_admin on public.audit_logs; create policy audit_read_admin on public.audit_logs for select using(public.is_admin());
commit;
